//! Complete actual reward-map/ordinal fold, retaining the original embedded
//! epochs independently of their outer map key or mint Vec ordinal.
use super::*;
use super::{state_columns::OriginalStateColumnsDataV1,original_rows::OriginalProjectionRowDataV1,reward_rows::OriginalRewardPoolRecordDataV1};
use oasis7_world_state::incremental_reward_budget_records::{CurrentRewardProjectionDeltaV1,RewardRecordKindV1 as Kind,RewardPoolProjectionPathRefV1 as Path};
use oasis7_formal_protocol::{incremental_execution::{ExecutionTransaction,ExecutionFence},incremental_state::MerkleNodeReader};
use std::cell::RefCell;
fn copy(value:&[u8],common:&mut FormalBoundedContextV1<'_>)->Result<ReservedValue<Vec<u8>>,BodyMutationError>{super::initial::capture(common,|out|std::io::Write::write_all(out,value).map_err(paid))}
pub(super) fn fold_reward_v1<M:MerkleNodeReader>(out:&mut OriginalStateColumnsDataV1,source:&CurrentRewardProjectionDeltaV1,tx:&ExecutionTransaction<'_,M>,common:&mut FormalBoundedContextV1<'_>,live:&ExecutionFence)->Result<(),BodyMutationError>{
 fold_rows_v1(out,source,tx,common,live)
}
pub(super) fn fold_rows_v1<M:MerkleNodeReader,T:super::cold_record_maps::RecordMapsV1>(out:&mut T,source:&CurrentRewardProjectionDeltaV1,tx:&ExecutionTransaction<'_,M>,common:&mut FormalBoundedContextV1<'_>,live:&ExecutionFence)->Result<(),BodyMutationError>{
 source.validate(tx,common.memory(),live)?;let mint_field=Kind::Mint.name();let before=out.sequence_data_v1(mint_field,common)?;if u64::try_from(before.len()).map_err(|_|invalid("reward parent length layout"))?!=source.before_mint_length(){return Err(invalid("reward original parent length"))}let common=RefCell::new(common);
 source.visit_entities_with_work_v1(|s,b|common.borrow_mut().charge(s,b).map_err(paid),|kind,semantic,key,before,after,mint|{let mut common=common.borrow_mut();let field=kind.name();if kind==Kind::Mint{let rows=out.sequence_data_v1(field,&mut common)?;if rows.row_data_v1(semantic,&mut common)?.is_some()!=before{return Err(invalid("reward mint before presence"))}let rows=if after{let value=mint.ok_or_else(||invalid("reward actual mint row missing"))?;let row=OriginalProjectionRowDataV1::from_original_encoded_data_v1(copy(semantic,&mut common)?,copy(key,&mut common)?,copy(value,&mut common)?,&mut common)?;rows.with_row_data_v1(row,&mut common)?}else{if mint.is_some(){return Err(invalid("removed reward mint value present"))}rows.without_row_data_v1(semantic,&mut common)?};return out.replace_original_sequence_data_v1(field,rows,&mut common)}
 let rows=out.map_data_v1(field,&mut common)?.ok_or_else(||invalid("reward pool rows missing"))?;let old=rows.row_data_v1(semantic,&mut common)?;if old.is_some()!=before{return Err(invalid("reward pool before presence"))}
 if !after{let rows=rows.without_row_data_v1(semantic,&mut common)?;return out.replace_original_map_data_v1(field,rows,&mut common)}
 if !before{let value=OriginalRewardPoolRecordDataV1::empty_for_new_actual_entity_v1(&mut common)?;let row=OriginalProjectionRowDataV1::from_reward_pool_data_v1(copy(semantic,&mut common)?,copy(key,&mut common)?,value,&mut common)?;let rows=rows.with_row_data_v1(row,&mut common)?;out.replace_original_map_data_v1(field,rows,&mut common)?;}else if old.and_then(|r|r.reward_pool_record_v1()).is_none(){return Err(invalid("reward pool resident kind"))}Ok(())})?;
 source.visit_pool_patches_with_work_v1(|s,b|common.borrow_mut().charge(s,b).map_err(paid),|semantic,key,path|{let mut common=common.borrow_mut();let field=Kind::Pool.name();let rows=out.map_data_v1(field,&mut common)?.ok_or_else(||invalid("reward pool rows missing"))?;let record=rows.row_data_v1(semantic,&mut common)?.and_then(|r|r.reward_pool_record_v1()).ok_or_else(||invalid("reward pool current row missing"))?;let value=match path{Path::Scalar(column,value)=>record.with_scalar_v1(column,value,&mut common)?,Path::Member(collection,id,after)=>{let semantic=super::initial::capture(&mut common,|out|oasis7_world_state::incremental_semantic_key::write_semantic_key_v1(id,out).map_err(paid))?;let key=super::capture_projection_json_data_v1(id,&mut common)?;let after=after.map(|v|super::capture_projection_json_data_v1(&v,&mut common)).transpose()?;record.with_member_v1(collection,semantic,key,after,&mut common)?}};let row=OriginalProjectionRowDataV1::from_reward_pool_data_v1(copy(semantic,&mut common)?,copy(key,&mut common)?,value,&mut common)?;let rows=rows.with_row_data_v1(row,&mut common)?;out.replace_original_map_data_v1(field,rows,&mut common)})?;
 source.visit_entities_with_work_v1(|s,b|common.borrow_mut().charge(s,b).map_err(paid),|kind,semantic,_key,_before,after,_mint|{if kind==Kind::Mint||!after{return Ok(())}let mut common=common.borrow_mut();let rows=out.map_data_v1(kind.name(),&mut common)?.ok_or_else(||invalid("reward pool rows missing"))?;let record=rows.row_data_v1(semantic,&mut common)?.and_then(|r|r.reward_pool_record_v1()).ok_or_else(||invalid("reward pool final row missing"))?;record.validate_complete_v1(&mut common)})?;
 let common=common.into_inner();if u64::try_from(out.sequence_data_v1(mint_field,common)?.len()).map_err(|_|invalid("reward current length layout"))?!=source.after_mint_length(){return Err(invalid("reward actual current length"))}source.validate(tx,common.memory(),live)
}
